package crypto

import (
	"encoding/base64"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// The fixtures live in testdata, generated by the committed Node script so
// nobody hand edits a vector. Regenerate with:
//
//	node scripts/gen-fixtures.mjs
func loadFixtures(t *testing.T) []fixtureVector {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "fixtures.json"))
	if err != nil {
		t.Fatalf("read fixtures: %v (regenerate with node scripts/gen-fixtures.mjs)", err)
	}
	var doc struct {
		Format  string          `json:"format"`
		Vectors []fixtureVector `json:"vectors"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("parse fixtures: %v", err)
	}
	if doc.Format != "ds1" {
		t.Fatalf("fixture format %q, want ds1", doc.Format)
	}
	return doc.Vectors
}

// The actual generator keeps itself out of short runs:
// go test ./internal/crypto -run TestGenerateGoFixtures
func TestGenerateGoFixtures(t *testing.T) {
	if testing.Short() || os.Getenv("DREAMSHARE_WRITE_FIXTURES") != "1" {
		t.Skip("fixture generation is opt in, DREAMSHARE_WRITE_FIXTURES=1, so a plain test run never rewrites the committed file")
	}
	gen := []struct {
		name    string
		purpose string
		id      string
		pt      []byte
	}{
		{"go-file-multiframe", PurposeFile, "gfile1", bytesRepeat(FramePlaintextMax + 299)},
		{"go-file-single", PurposeFile, "gfile2", []byte("go single frame payload")},
		{"go-file-empty", PurposeFile, "gfile3", nil},
		{"go-manifest", PurposeManifest, "", []byte(`{"title":"ct","files":[]}`)},
		{"go-check", PurposeCheck, "", bytesRepeat(16)},
		{"go-title", PurposeTitle, "", []byte("encrypted title")},
	}
	var out struct {
		Format  string          `json:"format"`
		Vectors []fixtureVector `json:"vectors"`
	}
	out.Format = "ds1"
	for _, g := range gen {
		if len(g.pt) == 0 && g.name != "go-file-empty" {
			t.Fatalf("vector %s is unexpectedly empty", g.name)
		}
		master := randomMaster(t)
		subkey := mustSubkey(t, master, SubkeyInfo(g.purpose, g.id))
		prefix, err := NewNoncePrefix()
		if err != nil {
			t.Fatal(err)
		}
		ct := sealAll(t, subkey, prefix, 0, "goshare1", g.purpose, g.pt)
		frag, err := EncodeFragmentKey(master)
		if err != nil {
			t.Fatal(err)
		}
		out.Vectors = append(out.Vectors, fixtureVector{
			Name: g.name, ShareID: "goshare1", Purpose: g.purpose, ID: g.id,
			MasterKey: frag, NoncePrefix: base64.RawURLEncoding.EncodeToString(prefix),
			Plaintext:  base64.StdEncoding.EncodeToString(g.pt),
			Ciphertext: base64.StdEncoding.EncodeToString(ct),
		})
	}
	raw, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join("testdata", "fixtures-go.json")
	if err := os.WriteFile(path, raw, 0o600); err != nil {
		t.Fatal(err)
	}
	t.Logf("wrote %s, run the vitest suite to verify the TypeScript twin opens it", path)
}

func bytesRepeat(n int) []byte {
	b := make([]byte, n)
	for i := range b {
		b[i] = byte(i % 251)
	}
	return b
}
